//! OpenChamber palettes resolved from the canonical theme definitions.
//!
//! `resources/themes.json` is generated by `bun run native:resources` from the
//! same resolver the web UI uses, so every color here is the value the
//! Electron client paints. Views read [`Palette`]; GPUI Kit components read the
//! Kit theme, which [`apply`] fills from the same palette.

use std::collections::HashMap;
use std::sync::Arc;

use gpui_kit::component::Theme;
use gpui_kit::component::highlighter::HighlightTheme;
use gpui_kit::component::theme::ThemeMode;
use gpui_kit::{App, Global, Hsla, Rgba};
use openchamber_native_core::send_config::{AgentColor, SyntaxPaletteEntry};
use serde::Deserialize;

const THEMES_JSON: &str = include_str!("../resources/themes.json");

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ThemeFile {
    default_light: String,
    default_dark: String,
    themes: Vec<ThemeEntry>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ThemeEntry {
    id: String,
    name: String,
    variant: String,
    colors: HashMap<String, String>,
    agent_palette: Vec<PaletteRole>,
}

#[derive(Deserialize)]
struct PaletteRole {
    index: usize,
    colorful: bool,
}

/// The syntax roles agent colors draw from, in `agentColorPalette`'s order.
const AGENT_SYNTAX_ROLES: [&str; 7] = [
    "keyword", "type", "function", "number", "string", "operator", "variable",
];

/// Tree-sitter captures and the syntax colors they take, as
/// `buildSyntaxTokenRules` (`lib/shiki/textMateThemeFromAppTheme.ts`) colors
/// the TextMate scopes that name the same things: each capture tries its
/// `syntax.tokens.*` names in order and falls back to a `syntax.base.*` role.
/// The flag marks the web's bold function names.
const CAPTURE_COLORS: &[(&str, &[&str], &str, bool)] = &[
    ("attribute", &["tagAttribute"], "type", false),
    ("boolean", &["boolean"], "type", false),
    ("comment", &[], "comment", false),
    ("comment.doc", &["commentDoc"], "comment", false),
    ("constant", &["constant"], "foreground", false),
    ("constructor", &["className", "class"], "function", false),
    ("embedded", &[], "foreground", false),
    ("emphasis", &[], "string", false),
    ("emphasis.strong", &["namespace"], "type", false),
    ("enum", &["enum"], "function", false),
    ("function", &[], "function", true),
    ("keyword", &[], "keyword", false),
    ("label", &["label", "variableGlobal"], "number", false),
    ("link_text", &[], "string", false),
    ("link_uri", &["url"], "string", false),
    ("number", &[], "number", false),
    ("operator", &[], "operator", false),
    ("preproc", &["preprocessor", "label"], "number", false),
    ("property", &["variableProperty"], "variable", false),
    ("punctuation", &["punctuation"], "comment", false),
    ("punctuation.bracket", &["punctuation"], "comment", false),
    ("punctuation.delimiter", &["punctuation"], "comment", false),
    ("punctuation.list_marker", &[], "type", false),
    ("punctuation.special", &["punctuation"], "comment", false),
    ("string", &[], "string", false),
    ("string.escape", &["stringEscape"], "foreground", false),
    ("string.regex", &["stringRegex"], "string", false),
    ("string.special", &[], "string", false),
    ("string.special.symbol", &[], "string", false),
    ("tag", &["tag"], "keyword", false),
    ("tag.doctype", &["tag"], "keyword", false),
    ("text.code.span", &[], "string", false),
    ("text.literal", &[], "string", false),
    ("title", &[], "type", false),
    ("type", &["interface"], "type", false),
    ("variable", &[], "variable", false),
    ("variable.special", &["variableGlobal"], "number", false),
    ("variant", &["constant"], "foreground", false),
];

/// Light or dark appearance.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Appearance {
    Light,
    Dark,
}

/// The semantic colors native views paint with.
#[derive(Clone, Debug, PartialEq)]
pub struct Palette {
    pub id: String,
    pub appearance: Appearance,
    pub background: Hsla,
    pub foreground: Hsla,
    pub muted: Hsla,
    pub muted_foreground: Hsla,
    pub elevated: Hsla,
    pub elevated_foreground: Hsla,
    pub subtle: Hsla,
    pub border: Hsla,
    pub hover: Hsla,
    pub active: Hsla,
    pub selection: Hsla,
    pub selection_foreground: Hsla,
    pub focus_ring: Hsla,
    pub primary: Hsla,
    pub primary_foreground: Hsla,
    pub primary_hover: Hsla,
    pub chat_background: Hsla,
    /// `--chat-divider`: the context meter's track.
    pub chat_divider: Hsla,
    pub user_message_background: Hsla,
    pub divider: Hsla,
    pub link: Hsla,
    pub inline_code: Hsla,
    pub inline_code_background: Hsla,
    pub markdown_bold: Hsla,
    pub syntax_background: Hsla,
    pub syntax_foreground: Hsla,
    /// `syntax.base.comment`, the terminal's bright black.
    pub syntax_comment: Hsla,
    /// Code highlighting from the theme's syntax tokens.
    pub highlight: Arc<HighlightTheme>,
    pub error: Hsla,
    pub warning: Hsla,
    pub success: Hsla,
    pub info: Hsla,
    /// Solid status fills, for surfaces such as the close button's hover.
    pub status_error: Hsla,
    pub status_error_foreground: Hsla,
    pub status_success: Hsla,
    pub status_warning: Hsla,
    pub status_warning_background: Hsla,
    pub status_info: Hsla,
    pub status_error_background: Hsla,
    /// Tool and reasoning rows (`--tools-*`).
    pub tools_border: Hsla,
    pub tools_icon: Hsla,
    pub tools_title: Hsla,
    pub tools_description: Hsla,
    /// Issue and change request state colours (`--pr-*`).
    pub pr_open: Hsla,
    pub pr_draft: Hsla,
    pub pr_blocked: Hsla,
    pub pr_merged: Hsla,
    pub pr_closed: Hsla,
    pub cursor: Hsla,
    /// `syntax.base.*` in `AGENT_SYNTAX_ROLES` order.
    pub agent_syntax: [Hsla; AGENT_SYNTAX_ROLES.len()],
    /// The theme's ordered, contrast-filtered agent palette.
    pub agent_palette: Vec<SyntaxPaletteEntry>,
}

impl Global for Palette {}

/// A built-in theme's canonical picker label and ID.
#[derive(Clone)]
pub(crate) struct ThemeOption {
    pub(crate) id: String,
    pub(crate) name: String,
    pub(crate) full_name: String,
    pub(crate) palette: Palette,
}

/// Resolves a host-owned definition before it can enter the active library.
pub(crate) fn from_definition(definition: &serde_json::Value) -> Result<ThemeOption, String> {
    let resolved =
        crate::theme_import::resolve_theme(definition).map_err(|error| error.code().to_owned())?;
    let mut colors = resolved.colors;
    for (name, fallback, alpha) in [
        ("chat.background", "surface.background", 1.0),
        ("chat.divider", "interactive.border", 1.0),
        ("chat.userMessageBackground", "surface.elevated", 1.0),
        ("markdown.link", "primary.base", 1.0),
        ("markdown.inlineCode", "syntax.base.string", 1.0),
        ("markdown.inlineCodeBackground", "chat.background", 1.0),
        ("markdown.bold", "surface.foreground", 1.0),
        ("tools.border", "interactive.border", 0.3),
        ("tools.icon", "surface.mutedForeground", 1.0),
        ("tools.title", "surface.foreground", 1.0),
        ("tools.description", "surface.mutedForeground", 0.6),
    ] {
        if !colors.contains_key(name) {
            let value = colors.get(fallback).ok_or("invalid")?.clone();
            let value = if alpha == 1.0 {
                value
            } else {
                crate::theme_import::css_opacity(&value, alpha)
            };
            colors.insert(name.into(), value);
        }
    }
    let dark = resolved.variant == "dark";
    let foreground = crate::theme_import::css_color_context(
        colors.get("surface.foreground").ok_or("invalid")?,
        dark,
    )
    .map_err(|_| "unsupported")?;
    let mut painted = HashMap::new();
    for (token, value) in &mut colors {
        let rgba = crate::theme_import::resolve_css_color(value, dark, Some(foreground))
            .map_err(|_| "unsupported")?;
        painted.insert(
            token.clone(),
            Hsla::from(Rgba {
                r: rgba[0],
                g: rgba[1],
                b: rgba[2],
                a: rgba[3],
            }),
        );
        // Kit's syntax-theme deserializer consumes hex. Main UI paint retains
        // floating channels in `painted`; conversion never rewrites the source.
        *value = format!(
            "#{:02x}{:02x}{:02x}{:02x}",
            (rgba[0] * 255.0).round() as u8,
            (rgba[1] * 255.0).round() as u8,
            (rgba[2] * 255.0).round() as u8,
            (rgba[3] * 255.0).round() as u8
        );
    }
    // External definitions never reach the generated-resource assertions below.
    for token in [
        "surface.background",
        "surface.foreground",
        "surface.muted",
        "surface.mutedForeground",
        "surface.elevated",
        "surface.elevatedForeground",
        "surface.subtle",
        "interactive.border",
        "interactive.hover",
        "interactive.active",
        "interactive.selection",
        "readable.selectionForeground",
        "interactive.focusRing",
        "primary.base",
        "primary.foreground",
        "primary.hover",
        "chat.background",
        "chat.divider",
        "chat.userMessageBackground",
        "markdown.link",
        "markdown.inlineCode",
        "markdown.inlineCodeBackground",
        "markdown.bold",
        "syntax.base.background",
        "syntax.base.foreground",
        "syntax.base.comment",
        "readable.status.error",
        "readable.status.warning",
        "readable.status.success",
        "readable.status.info",
        "status.error",
        "status.errorForeground",
        "status.success",
        "status.warning",
        "status.warningBackground",
        "status.info",
        "status.errorBackground",
        "tools.border",
        "tools.icon",
        "tools.title",
        "tools.description",
        "pr.open",
        "pr.draft",
        "pr.blocked",
        "pr.merged",
        "pr.closed",
        "interactive.cursor",
        "syntax.base.keyword",
        "syntax.base.type",
        "syntax.base.function",
        "syntax.base.number",
        "syntax.base.string",
        "syntax.base.operator",
        "syntax.base.variable",
    ] {
        if !painted.contains_key(token) {
            return Err("invalid".into());
        }
    }
    let entry = ThemeEntry {
        id: resolved.id,
        name: resolved.name,
        variant: resolved.variant,
        colors,
        agent_palette: resolved
            .agent_palette
            .into_iter()
            .map(|role| PaletteRole {
                index: role.index,
                colorful: role.colorful,
            })
            .collect(),
    };
    let suffix = if entry.variant == "light" {
        " Light"
    } else {
        " Dark"
    };
    Ok(ThemeOption {
        id: entry.id.clone(),
        full_name: entry.name.clone(),
        name: entry
            .name
            .strip_suffix(suffix)
            .unwrap_or(&entry.name)
            .to_owned(),
        palette: Palette::from_entry_colors(&entry, |token| painted[token]),
    })
}

pub(crate) fn options(appearance: Appearance) -> Vec<ThemeOption> {
    let variant = match appearance {
        Appearance::Light => "light",
        Appearance::Dark => "dark",
    };
    let mut options: Vec<_> = theme_file()
        .themes
        .into_iter()
        .filter(|entry| entry.variant == variant)
        .map(|entry| {
            let suffix = if appearance == Appearance::Light {
                " Light"
            } else {
                " Dark"
            };
            ThemeOption {
                id: entry.id.clone(),
                full_name: entry.name.clone(),
                name: entry
                    .name
                    .strip_suffix(suffix)
                    .unwrap_or(&entry.name)
                    .to_owned(),
                palette: Palette::from_entry(&entry),
            }
        })
        .collect();
    options.sort_by(|a, b| a.name.cmp(&b.name));
    options
}

impl Palette {
    /// The default palette for an appearance.
    pub fn default_for(appearance: Appearance) -> Self {
        let file = theme_file();
        let id = match appearance {
            Appearance::Light => &file.default_light,
            Appearance::Dark => &file.default_dark,
        };
        Self::by_id(id).expect("the generated themes include both default palettes")
    }

    /// A built-in palette by its theme ID.
    pub fn by_id(id: &str) -> Option<Self> {
        let file = theme_file();
        let entry = file.themes.iter().find(|entry| entry.id == id)?;
        Some(Self::from_entry(entry))
    }

    fn from_entry(entry: &ThemeEntry) -> Self {
        let color = |token: &str| -> Hsla {
            let value = entry
                .colors
                .get(token)
                .unwrap_or_else(|| panic!("generated theme {} lacks the {token} token", entry.id));
            parse_hex(value).unwrap_or_else(|| panic!("theme {} has a non-hex {token}", entry.id))
        };
        Self::from_entry_colors(entry, color)
    }

    fn from_entry_colors(entry: &ThemeEntry, color: impl Fn(&str) -> Hsla) -> Self {
        Self {
            id: entry.id.clone(),
            appearance: if entry.variant == "dark" {
                Appearance::Dark
            } else {
                Appearance::Light
            },
            background: color("surface.background"),
            foreground: color("surface.foreground"),
            muted: color("surface.muted"),
            muted_foreground: color("surface.mutedForeground"),
            elevated: color("surface.elevated"),
            elevated_foreground: color("surface.elevatedForeground"),
            subtle: color("surface.subtle"),
            border: color("interactive.border"),
            hover: color("interactive.hover"),
            active: color("interactive.active"),
            selection: color("interactive.selection"),
            selection_foreground: color("readable.selectionForeground"),
            focus_ring: color("interactive.focusRing"),
            primary: color("primary.base"),
            primary_foreground: color("primary.foreground"),
            primary_hover: color("primary.hover"),
            chat_background: color("chat.background"),
            chat_divider: color("chat.divider"),
            user_message_background: color("chat.userMessageBackground"),
            divider: color("chat.divider"),
            link: color("markdown.link"),
            inline_code: color("markdown.inlineCode"),
            inline_code_background: color("markdown.inlineCodeBackground"),
            markdown_bold: color("markdown.bold"),
            syntax_background: color("syntax.base.background"),
            syntax_foreground: color("syntax.base.foreground"),
            syntax_comment: color("syntax.base.comment"),
            highlight: Arc::new(highlight_theme(entry)),
            error: color("readable.status.error"),
            warning: color("readable.status.warning"),
            success: color("readable.status.success"),
            info: color("readable.status.info"),
            status_error: color("status.error"),
            status_error_foreground: color("status.errorForeground"),
            status_success: color("status.success"),
            status_warning: color("status.warning"),
            status_warning_background: color("status.warningBackground"),
            status_info: color("status.info"),
            status_error_background: color("status.errorBackground"),
            tools_border: color("tools.border"),
            tools_icon: color("tools.icon"),
            tools_title: color("tools.title"),
            tools_description: color("tools.description"),
            pr_open: color("pr.open"),
            pr_draft: color("pr.draft"),
            pr_blocked: color("pr.blocked"),
            pr_merged: color("pr.merged"),
            pr_closed: color("pr.closed"),
            cursor: color("interactive.cursor"),
            agent_syntax: AGENT_SYNTAX_ROLES.map(|role| color(&format!("syntax.base.{role}"))),
            agent_palette: entry
                .agent_palette
                .iter()
                .map(|role| SyntaxPaletteEntry {
                    index: role.index,
                    colorful: role.colorful,
                })
                .collect(),
        }
    }
}

impl Palette {
    /// The color of an agent's label and icon, as `useAgentColors` resolves it.
    pub fn agent_color(&self, color: &AgentColor) -> Hsla {
        match color {
            AgentColor::Configured(hex) => parse_hex(hex).unwrap_or(self.status_success),
            AgentColor::Success => self.status_success,
            AgentColor::Syntax { index, .. } => self
                .agent_syntax
                .get(*index)
                .copied()
                .unwrap_or(self.status_success),
        }
    }
}

/// Installs `palette` for native views and GPUI Kit components.
pub fn apply(palette: Palette, cx: &mut App) {
    let mode = match palette.appearance {
        Appearance::Light => ThemeMode::Light,
        Appearance::Dark => ThemeMode::Dark,
    };
    // Changing the mode reloads the Kit's own colors, so colors are written
    // in a second update.
    Theme::change(mode, None, cx);
    Theme::update(cx, |theme| {
        theme.background = palette.background;
        theme.foreground = palette.foreground;
        theme.border = palette.border;
        theme.input = palette.border;
        theme.ring = palette.focus_ring;
        theme.caret = palette.cursor;
        theme.selection = palette.selection;
        theme.muted = palette.muted;
        theme.muted_foreground = palette.muted_foreground;
        theme.accent = palette.hover;
        theme.accent_foreground = palette.foreground;
        theme.primary = palette.primary;
        theme.primary_hover = palette.primary_hover;
        theme.primary_foreground = palette.primary_foreground;
        theme.secondary = palette.elevated;
        theme.secondary_hover = palette.hover;
        theme.secondary_foreground = palette.elevated_foreground;
        theme.popover = palette.elevated;
        theme.popover_foreground = palette.elevated_foreground;
        theme.sidebar = palette.muted;
        theme.sidebar_foreground = palette.foreground;
        theme.sidebar_border = palette.border;
        theme.sidebar_accent = palette.selection;
        theme.sidebar_accent_foreground = palette.selection_foreground;
        theme.list_hover = palette.hover;
        theme.list_active = palette.selection;
        theme.link = palette.link;
        theme.danger = palette.error;
        theme.warning = palette.warning;
        theme.success = palette.success;
        theme.info = palette.info;
        theme.scrollbar_thumb = palette.active;
        theme.scrollbar_thumb_hover = palette.border;
        theme.window_border = palette.border;
        theme.highlight_theme = palette.highlight.clone();
    });
    cx.set_global(palette);
}

/// The theme's code highlighting, in the Zed format Kit reads.
fn highlight_theme(entry: &ThemeEntry) -> HighlightTheme {
    let token = |name: &str| entry.colors.get(name).cloned();
    let mut syntax = serde_json::Map::new();
    for (capture, tokens, role, bold) in CAPTURE_COLORS {
        let color = tokens
            .iter()
            .find_map(|name| token(&format!("syntax.tokens.{name}")))
            .or_else(|| token(&format!("syntax.base.{role}")));
        let Some(color) = color else {
            continue;
        };
        let mut style = serde_json::json!({ "color": color });
        if *bold {
            style["font_weight"] = serde_json::json!(700);
        }
        syntax.insert((*capture).to_owned(), style);
    }
    serde_json::from_value(serde_json::json!({
        "name": entry.id,
        "appearance": entry.variant,
        "style": {
            "editor.background": token("syntax.base.background"),
            "editor.foreground": token("syntax.base.foreground"),
            "editor.line_number": token("syntax.highlights.lineNumber"),
            "editor.active_line_number": token("syntax.highlights.lineNumberActive"),
            "syntax": syntax,
        },
    }))
    .unwrap_or_else(|error| panic!("theme {} builds a highlight theme: {error}", entry.id))
}

fn theme_file() -> ThemeFile {
    serde_json::from_str(THEMES_JSON).expect("resources/themes.json is generated valid JSON")
}

/// Parses `#rgb`, `#rgba`, `#rrggbb` and `#rrggbbaa`.
fn parse_hex(value: &str) -> Option<Hsla> {
    let digits = value.strip_prefix('#')?;
    let expanded: String = match digits.len() {
        3 | 4 => digits.chars().flat_map(|digit| [digit, digit]).collect(),
        6 | 8 => digits.to_owned(),
        _ => return None,
    };
    let channel = |index: usize| -> Option<f32> {
        let byte = u8::from_str_radix(expanded.get(index * 2..index * 2 + 2)?, 16).ok()?;
        Some(f32::from(byte) / 255.0)
    };
    let alpha = if expanded.len() == 8 {
        channel(3)?
    } else {
        1.0
    };
    Some(Hsla::from(Rgba {
        r: channel(0)?,
        g: channel(1)?,
        b: channel(2)?,
        a: alpha,
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_every_hex_form() {
        let opaque = parse_hex("#ff0000").expect("valid");
        assert!((opaque.a - 1.0).abs() < f32::EPSILON);
        let translucent = parse_hex("#ffffff0f").expect("valid");
        assert!((translucent.a - 15.0 / 255.0).abs() < 1e-6);
        assert!(parse_hex("#abc").is_some());
        assert!(parse_hex("red").is_none());
        assert!(parse_hex("#12345").is_none());
    }

    #[test]
    fn imported_palette_current_color_keeps_missing_alpha_distinct_from_zero() {
        let fixtures: serde_json::Value =
            serde_json::from_str(include_str!("theme_import/fixtures.json")).expect("fixtures");
        for (alpha, expected) in [
            ("none", [150.0 / 255.0, 150.0 / 255.0, 75.0 / 255.0, 0.4]),
            ("0", [100.0 / 255.0, 200.0 / 255.0, 100.0 / 255.0, 0.2]),
        ] {
            let mut definition = fixtures["definitions"][0]["definition"].clone();
            definition["colors"]["surface"]["foreground"] =
                serde_json::json!(format!("rgb(200 100 50 / {alpha})"));
            definition["colors"]["interactive"]["border"] =
                serde_json::json!("color-mix(in srgb, currentColor, rgb(100 200 100 / 0.4))");
            let option = from_definition(&definition).expect("imported palette");
            let actual = Rgba::from(option.palette.chat_divider);
            for (channel, expected) in [actual.r, actual.g, actual.b, actual.a]
                .into_iter()
                .zip(expected)
            {
                assert!((channel - expected).abs() < 1e-6, "alpha={alpha}");
            }
        }
    }

    #[test]
    fn every_generated_theme_resolves() {
        let file = theme_file();
        assert!(file.themes.len() > 2);
        for entry in &file.themes {
            let palette = Palette::by_id(&entry.id).expect("theme exists");
            assert_eq!(palette.id, entry.id);
            assert!(
                palette.highlight.keyword.is_some(),
                "{} colors keywords",
                entry.id
            );
        }
        assert_eq!(
            Palette::default_for(Appearance::Dark).appearance,
            Appearance::Dark
        );
        assert_eq!(
            Palette::default_for(Appearance::Light).appearance,
            Appearance::Light
        );
    }
}
